question.solution:
def eval_infix(expr):
    prec = {'+': 1, '-': 1, '*': 2, '/': 2}
    nums = []
    ops = []

    def apply_top():
        if len(nums) < 2 or not ops:
            raise ValueError('表达式非法：%r' % (expr,))
        right = nums.pop()
        left = nums.pop()
        op = ops.pop()
        if op == '+':
            nums.append(left + right)
        elif op == '-':
            nums.append(left - right)
        elif op == '*':
            nums.append(left * right)
        else:
            nums.append(int(left / right))

    i = 0
    n = len(expr)
    while i < n:
        ch = expr[i]
        if ch.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            nums.append(int(expr[i:j]))
            i = j
        elif ch == '(':
            ops.append(ch)
            i += 1
        elif ch == ')':
            while ops and ops[-1] != '(':
                apply_top()
            if not ops:
                raise ValueError('括号不匹配：%r' % (expr,))
            ops.pop()
            i += 1
        elif ch in prec:
            while ops and ops[-1] != '(' and prec[ops[-1]] >= prec[ch]:
                apply_top()
            ops.append(ch)
            i += 1
        else:
            raise ValueError('非法字符：%r' % (ch,))
    while ops:
        if ops[-1] == '(':
            raise ValueError('括号不匹配：%r' % (expr,))
        apply_top()
    if len(nums) != 1:
        raise ValueError('表达式非法：%r' % (expr,))
    return nums[0]

print(eval_infix('3+4*5'))
print(eval_infix('(3+4)*5'))
print(eval_infix('10+20*3'))
print(eval_infix('((2+3)*4-5)/3'))

